DO $test$ DECLARE a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();BEGIN
 INSERT INTO auth.users(id) VALUES(a),(b),(c);INSERT INTO public.profiles(user_id,account_state) VALUES(a,'active'),(b,'active'),(c,'active');
 INSERT INTO public.user_privacy_settings(user_id,profile_visibility,contact_permission) SELECT v.id,'private','friends' FROM (VALUES(a),(b),(c)) v(id);
 INSERT INTO public.user_eligibility(user_id,status,verification_method,verification_version,verified_at) SELECT v.id,'eligible','test','test',now() FROM (VALUES(a),(b),(c)) v(id);
 INSERT INTO public.policy_acceptances(user_id,policy_version_id) SELECT v.id,p.id FROM (VALUES(a),(b),(c)) v(id) CROSS JOIN public.policy_versions p WHERE p.mandatory AND p.published_at<=now() AND p.retired_at IS NULL;
 INSERT INTO public.friendships(user_low,user_high) VALUES(least(a,b),greatest(a,b));PERFORM set_config('test.dmn_a',a::text,false);PERFORM set_config('test.dmn_b',b::text,false);PERFORM set_config('test.dmn_c',c::text,false);
 IF has_function_privilege('anon','public.list_own_direct_message_notifications(timestamptz,uuid)','EXECUTE') OR has_table_privilege('authenticated','public.notifications','SELECT') THEN RAISE EXCEPTION 'Unwanted access';END IF;
END $test$;
SET ROLE authenticated;SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_a'),false);
SELECT set_config('test.dmn_cid',public.start_friend_conversation(current_setting('test.dmn_b')::uuid)::text,false);
SELECT set_config('test.dmn_msg',public.send_friend_message(current_setting('test.dmn_cid')::uuid,'Sensitive content never in notice')::text,false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_direct_message_notifications()) THEN RAISE EXCEPTION 'Sender sees own notice';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_b'),false);
DO $test$ DECLARE n uuid;t timestamptz;BEGIN
 IF (SELECT count(*) FROM public.list_own_direct_message_notifications())<>1 THEN RAISE EXCEPTION 'Notice missing';END IF;
 SELECT id INTO n FROM public.list_own_direct_message_notifications() WHERE conversation_id=current_setting('test.dmn_cid')::uuid;PERFORM set_config('test.dmn_n',n::text,false);
 PERFORM public.mark_own_direct_message_notification_read(n);SELECT read_at INTO t FROM public.list_own_direct_message_notifications() WHERE id=n;
 IF t IS NULL THEN RAISE EXCEPTION 'Mark read failed';END IF;PERFORM public.mark_own_direct_message_notification_read(n);
 IF (SELECT read_at FROM public.list_own_direct_message_notifications() WHERE id=n)<>t THEN RAISE EXCEPTION 'Read not idempotent';END IF;
 BEGIN PERFORM * FROM public.list_own_direct_message_notifications(now(),null);RAISE EXCEPTION 'Bad cursor';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_c'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_direct_message_notifications()) THEN RAISE EXCEPTION 'Other user sees notice';END IF;
 BEGIN PERFORM public.mark_own_direct_message_notification_read(current_setting('test.dmn_n')::uuid);RAISE EXCEPTION 'Other user read notice';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_a'),false);
SELECT public.hide_own_friend_message(current_setting('test.dmn_msg')::uuid);
SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_b'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_direct_message_notifications()) THEN RAISE EXCEPTION 'Hidden message notice shown';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_a'),false);
SELECT public.send_friend_message(current_setting('test.dmn_cid')::uuid,'Before block');
SELECT set_config('request.jwt.claim.sub',current_setting('test.dmn_b'),false);
DO $test$ BEGIN IF (SELECT count(*) FROM public.list_own_direct_message_notifications())<>1 THEN RAISE EXCEPTION 'Notice not visible';END IF;END $test$;
SELECT public.block_user(current_setting('test.dmn_a')::uuid);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_direct_message_notifications()) THEN RAISE EXCEPTION 'Blocked notice visible';END IF;END $test$;
RESET ROLE;
UPDATE public.profiles SET account_state='suspended' WHERE user_id=current_setting('test.dmn_b')::uuid;
SET ROLE authenticated;
DO $test$ BEGIN BEGIN PERFORM * FROM public.list_own_direct_message_notifications();RAISE EXCEPTION 'Suspended notice access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $test$;
RESET ROLE;
